package gen

import (
	"context"

	"github.com/shibukawa/ebigentserver/samples/tictactoe/ttt"
	"github.com/shibukawa/ebigentserver/session"
)

// Decide is the compiled decision list. Earlier cases take precedence,
// exactly as the chips were mined and approved.
func Decide(obs ttt.Sight) (ttt.Move, bool) {
	switch {
	case obs.Board[0] == ttt.Empty:
		// chip cell_0_empty → play_0 (coverage 200, counterexamples 0)
		return ttt.Move{Cell: 0}, true
	case obs.Board[1] == ttt.Empty:
		// chip cell_1_empty → play_1 (coverage 176, counterexamples 0)
		return ttt.Move{Cell: 1}, true
	case obs.Board[2] == ttt.Empty:
		// chip cell_2_empty → play_2 (coverage 150, counterexamples 0)
		return ttt.Move{Cell: 2}, true
	case obs.Board[3] == ttt.Empty:
		// chip cell_3_empty → play_3 (coverage 66, counterexamples 0)
		return ttt.Move{Cell: 3}, true
	case obs.Board[4] == ttt.Empty:
		// chip cell_4_empty → play_4 (coverage 52, counterexamples 0)
		return ttt.Move{Cell: 4}, true
	case obs.Board[5] == ttt.Empty:
		// chip cell_5_empty → play_5 (coverage 10, counterexamples 0)
		return ttt.Move{Cell: 5}, true
	case obs.Board[6] == ttt.Empty:
		// chip cell_6_empty → play_6 (coverage 20, counterexamples 0)
		return ttt.Move{Cell: 6}, true
	case obs.Board[7] == ttt.Empty:
		// chip cell_7_empty → play_7 (coverage 6, counterexamples 0)
		return ttt.Move{Cell: 7}, true
	case obs.Board[8] == ttt.Empty:
		// chip cell_8_empty → play_8 (coverage 6, counterexamples 0)
		return ttt.Move{Cell: 8}, true
	}
	var zero ttt.Move
	return zero, false
}

// DistilledAgent seats the compiled policy behind api:agent-interface: an
// ordinary agent, indistinguishable from a hand-written bot.
type DistilledAgent struct {
	last ttt.Sight
	has  bool
}

func (*DistilledAgent) Joined(session.SlotID) {}

func (a *DistilledAgent) Observe(obs ttt.Sight) { a.last, a.has = obs, true }

func (a *DistilledAgent) Decide(context.Context) (ttt.Move, bool) {
	if !a.has {
		var zero ttt.Move
		return zero, false
	}
	return Decide(a.last)
}

func (*DistilledAgent) Ended(session.Result) {}

// actionName maps a decided action back to its vocabulary term, for
// the generated episode-fixture tests.
func actionName(a ttt.Move) string {
	switch a {
	case ttt.Move{Cell: 0}:
		return "play_0"
	case ttt.Move{Cell: 1}:
		return "play_1"
	case ttt.Move{Cell: 2}:
		return "play_2"
	case ttt.Move{Cell: 3}:
		return "play_3"
	case ttt.Move{Cell: 4}:
		return "play_4"
	case ttt.Move{Cell: 5}:
		return "play_5"
	case ttt.Move{Cell: 6}:
		return "play_6"
	case ttt.Move{Cell: 7}:
		return "play_7"
	case ttt.Move{Cell: 8}:
		return "play_8"
	}
	return ""
}
